SELECT * FROM ( SELECT bm.bp_id, bm.bp_code, bm.bp_name, bm.extra_nam, mr.bp_type, bm.domestic_oversea, bm.local_nonlocal, bm.org_type, bm.start_active_date, bm.end_active_date, bm.CREATED_BY, bm.company_id, ( SELECT bt.description FROM hls_bp_type bt WHERE bt.bp_type = mr.bp_type ) bp_type_desc, mr.bp_category, ( CASE WHEN ( SELECT COUNT(*) FROM hls_user_relationship hur WHERE hur.RELATION_DOCUMENT_ID = bm.bp_id AND hur.RELATION_DOCUMENT_CATEGORY='HLS_BP_MASTER' AND hur.RELATION_TYPE='P2D' AND hur.source_event='HLS_BP_MASTER.COLLECT' and hur.user_id = #{userId} ) > 0 THEN 'Y' ELSE 'N' END ) collectFlag FROM hls_bp_master bm, hls_bp_master_role mr WHERE bm.bp_id = mr.bp_id AND bm.enabled_flag = 'Y' and mr.enabled_flag = 'Y' ) v WHERE v.bp_category = 'CREDIT_ORGANIZATION' and v.company_id=#{request.companyId}
and v.bp_type in
#{item}
and v.org_type in
#{item}
and v.domestic_oversea in
#{item}
and v.local_nonlocal in
#{item}
and v.collectFlag in
#{item}
and v.bp_code like concat('%',concat(#{bpCode},'%'))
and v.bp_name like concat('%',concat(#{bpName},'%'))
and v.extra_nam like concat('%',concat(#{extraNam},'%'))
ORDER BY v.bp_id DESC

select hbm.bp_id, hbm.bp_code, hbm.bp_name, hbm.rele_com_flag, hbm.extra_nam, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code_id = scvb.code_id and scb.code = 'CSH.BANK_ORG_TYPE' and scvb.value = hbm.org_type) org_type_desc, hbmr.bp_type, hbt.description bp_type_desc, hbm.domestic_oversea,hbm.local_nonlocal, /*(SELECT hbmci.contact_person FROM hls_bp_master_contact_info hbmci WHERE hbmci.bp_id = hbm.bp_id AND hbmci.position = 'BUSINESS_MANAGER' ORDER BY hbmci.contact_info_id ASC offset 0 rows FETCH FIRST 1 rows ONLY) AS contact_person, (SELECT hbmci.cell_phone FROM hls_bp_master_contact_info hbmci WHERE hbmci.bp_id = hbm.bp_id AND hbmci.position = 'BUSINESS_MANAGER' ORDER BY hbmci.contact_info_id ASC offset 0 rows FETCH FIRST 1 rows ONLY) AS cell_phone, (SELECT hbmci.phone FROM hls_bp_master_contact_info hbmci WHERE hbmci.bp_id = hbm.bp_id AND hbmci.position = 'BUSINESS_MANAGER' ORDER BY hbmci.contact_info_id ASC offset 0 rows FETCH FIRST 1 rows ONLY) AS phone, (SELECT hbmci.email FROM hls_bp_master_contact_info hbmci WHERE hbmci.bp_id = hbm.bp_id AND hbmci.position = 'BUSINESS_MANAGER' ORDER BY hbmci.contact_info_id ASC offset 0 rows FETCH FIRST 1 rows ONLY) AS email, (SELECT hbma.address FROM hls_bp_master_address hbma WHERE hbma.bp_id = hbm.bp_id AND hbma.address_type = 'MAILING_ADDRESS' FETCH FIRST 1 rows ONLY) AS address, (SELECT hbma.zipcode FROM hls_bp_master_address hbma WHERE hbma.bp_id = hbm.bp_id AND hbma.address_type = 'MAILING_ADDRESS' FETCH FIRST 1 rows ONLY) AS zipcode*/ (SELECT hbmci.contact_person FROM hls_bp_master_contact_info hbmci WHERE hbmci.contact_info_id = get_bp_contract_info_last(p_bp_id => hbm.bp_id, p_position => 'BUSINESS_MANAGER')) AS contact_person, (SELECT hbmci.cell_phone FROM hls_bp_master_contact_info hbmci WHERE hbmci.contact_info_id = get_bp_contract_info_last(p_bp_id => hbm.bp_id, p_position => 'BUSINESS_MANAGER')) AS cell_phone, (SELECT hbmci.phone FROM hls_bp_master_contact_info hbmci WHERE hbmci.contact_info_id = get_bp_contract_info_last(p_bp_id => hbm.bp_id, p_position => 'BUSINESS_MANAGER')) AS phone, (SELECT hbmci.email FROM hls_bp_master_contact_info hbmci WHERE hbmci.contact_info_id = get_bp_contract_info_last(p_bp_id => hbm.bp_id, p_position => 'BUSINESS_MANAGER')) AS email, (SELECT hbma.address FROM hls_bp_master_address hbma WHERE hbma.address_id = get_bp_address_last(p_bp_id => hbm.bp_id, p_address_type => 'MAILING_ADDRESS')) AS address, (SELECT hbma.zipcode FROM hls_bp_master_address hbma WHERE hbma.address_id = get_bp_address_last(p_bp_id => hbm.bp_id, p_address_type => 'MAILING_ADDRESS')) AS zipcode from hls_bp_master hbm,hls_bp_master_role hbmr,hls_bp_type hbt
hbm.bp_id = hbmr.bp_id and hbmr.bp_category = 'CREDIT_ORGANIZATION' and hbmr.bp_type = hbt.bp_type and hbmr.enabled_flag = 'Y' and hbm.company_id = #{request.companyId}
and hbm.bp_id = #{bpId}
and hbm.bp_code like concat(concat('%',#{bpCode}),'%')
and hbm.bp_name like concat(concat('%',#{bpName}),'%')
order by hbm.bp_code desc
